contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint balanceAmount) public payable {
        require(balanceAmount == 0);

        bool reverted;
        uint256 beforeCaller = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeC = address(c).balance;

        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterCaller = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterC = address(c).balance;

        assert(afterCaller == beforeCaller && afterC == beforeC);
    }

    receive() external payable {}
}

